class ExpressionEvaluator:
    def __init__(self, expr: str):
        self.expr = expr.replace(' ', '')
        self.index = 0

    def parse(self):
        value = self.add_subtract()
        return value

    def add_subtract(self):
        value = self.multiply_divide()
        while self.index < len(self.expr):
            if self.expr[self.index] == '+':
                self.index += 1
                value += self.multiply_divide()
            elif self.expr[self.index] == '-':
                self.index += 1
                value -= self.multiply_divide()
            else:
                break
        return value

    def multiply_divide(self):
        value = self.terminal()
        while self.index < len(self.expr):
            if self.expr[self.index] == '*':
                self.index += 1
                value *= self.terminal()
            elif self.expr[self.index] == '/':
                self.index += 1
                value /= self.terminal()
            else:
                break
        return value

    def terminal(self):
        if self.expr[self.index] == '(':
            self.index += 1
            value = self.add_subtract()
            self.index += 1  # Skip the closing parenthesis
            return value
        else:
            start = self.index
            while (self.index < len(self.expr) and 
                   (self.expr[self.index].isdigit() or self.expr[self.index] == '.')):
                self.index += 1
            return float(self.expr[start:self.index])


def evaluate(expr: str) -> float:
    """Evaluates a mathematical expression using a recursive descent parser approach."""
    evaluator = ExpressionEvaluator(expr)
    return evaluator.parse()

class ShuntingYard:
    def __init__(self):
        self.output_queue = []
        self.operator_stack = []

    def precedence(self, operator: str) -> int:
        if operator in ('+', '-'):
            return 1
        if operator in ('*', '/'):
            return 2
        return 0

    def is_operator(self, token: str) -> bool:
        return token in ('+', '-', '*', '/')

    def shunting_yard(self, expression: str):
        tokens = self.tokenize(expression)
        for token in tokens:
            if token.isnumeric() or '.' in token:
                self.output_queue.append(float(token))
            elif self.is_operator(token):
                while (self.operator_stack and
                       self.precedence(self.operator_stack[-1]) >= self.precedence(token)):
                    self.output_queue.append(self.operator_stack.pop())
                self.operator_stack.append(token)
            elif token == '(':
                self.operator_stack.append(token)
            elif token == ')':
                while self.operator_stack and self.operator_stack[-1] != '(':
                    self.output_queue.append(self.operator_stack.pop())
                self.operator_stack.pop()  # pop the '('

        while self.operator_stack:
            self.output_queue.append(self.operator_stack.pop())

    def tokenize(self, expression: str):
        tokens = []
        number = ''
        for char in expression:
            if char in '0123456789.':
                number += char
            else:
                if number:
                    tokens.append(number)
                    number = ''
                if char in '()+-*/':
                    tokens.append(char)
        if number:
            tokens.append(number)
        return tokens

    def evaluate_rpn(self) -> float:
        stack = []
        for token in self.output_queue:
            if isinstance(token, float):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(a / b)
        return stack[0]

