    """Evaluates a mathematical expression using the shunting-yard algorithm to convert infix notation to postfix notation (RPN), which is then evaluated."""

    def to_postfix(expression):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        output = []
        operators = []
        num = ''

        for char in expression:
            if char.isdigit() or char == '.':
                num += char
            else:
